import unittest
from candidate import circular_shift

class TestCircularShift(unittest.TestCase):
    def test_circular_shift_normal_case(self):
        self.assertEqual(circular_shift(1234, 1), "4312")
        self.assertEqual(circular_shift(1234, 2), "3412")
        self.assertEqual(circular_shift(1234, 4), "1234")

    def test_circular_shift_shift_more_than_digits(self):
        self.assertEqual(circular_shift(1234, 5), "4321")

    def test_circular_shift_empty_string(self):
        self.assertEqual(circular_shift("", 0), "")
        self.assertEqual(circular_shift("", 1), "")

    def test_circular_shift_none_input(self):
        with self.assertRaises(TypeError):
            circular_shift(None, 1)

    def test_circular_shift_non_integer_input(self):
        with self.assertRaises(TypeError):
            circular_shift(123.4, 1)

    def test_circular_shift_negative_shift(self):
        with self.assertRaises(TypeError):
            circular_shift(1234, -1)

    def test_circular_shift_negative_integer_input(self):
        with self.assertRaises(TypeError):
            circular_shift(-1234, 1)

    def test_circular_shift_large_integer_input(self):
        self.assertEqual(circular_shift(12345678901234567890, 15), "8765094001234567")
        self.assertEqual(circular_shift(12345678901234567890, 20), "12345678901234567890")

if __name__ == '__main__':
    unittest.main()
